 "path": "/home/USER/continual-arc-baselines/.workbench/stage1/HPL0-hermes-luna6-medium-fresh0/frozen/held-out-reference/play/users/u015/system/state/workspace/programs/task-82572c94.py",
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    frames = {}
    for color in range(1, 10):
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not cells:
            continue
        r0, r1 = min(r for r,c in cells), max(r for r,c in cells)
        c0, c1 = min(c for r,c in cells), max(c for r,c in cells)
        if len(cells) == 2*(r1-r0+1)+2*(c1-c0+1)-4 and r1-r0 >= 2 and c1-c0 >= 2:
            border = all(grid[r][c] == color for r in range(r0,r1+1) for c in (c0,c1)) and all(grid[r][c] == color for c in range(c0,c1+1) for r in (r0,r1))
            if border:
                frames[color] = (r0,r1,c0,c1)
    # Scatter objects of the other non-background/non-noise colors in frames.
    for color, (r0,r1,c0,c1) in frames.items():
        inner = [(r,c) for r in range(r0+1,r1) for c in range(c0+1,c1)]
        if not inner: continue
        for r,c in inner: out[r][c] = 0
        # Use the distinct non-frame colors as a repeated checker / stripe pattern.
        objs = {}
        for r in range(h):
            for c in range(w):
                v = grid[r][c]
                if v not in (0,5,color): objs.setdefault(v, []).append((r,c))
        # select color with isolated markers; demo shows single object's color 3.
        if objs:
            v = max(objs, key=lambda x: len(objs[x]))
            # diagonal alternating pattern, phase aligned to top-left interior
            for r,c in inner:
                if (r-r0 + c-c0) % 2 == 1: out[r][c] = v
    # Remove loose 5s, which are background noise
    for r in range(h):
        for c in range(w):
            if out[r][c] == 5: out[r][c] = 0
    return out

if __name__ == '__main__':
    pass
