 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0]*w for _ in range(h)]
    frames = []
    # Detect rectangular frames of uniform color (all cells on perimeter, empty interior).
    for color in range(1, 10):
        cells = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not cells: continue
        r0,r1=min(r for r,c in cells),max(r for r,c in cells)
        c0,c1=min(c for r,c in cells),max(c for r,c in cells)
        perimeter = {(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1) if r in (r0,r1) or c in (c0,c1)}
        if set(cells) == perimeter and r1-r0 >= 3 and c1-c0 >= 3:
            frames.append((color,r0,r1,c0,c1))
    # Each frame receives the color of the separate singleton marker nearest to it;
    # the sparse distractor fields are discarded. Motif is checkerboard, starting at inner NW cell.
    marker_colors = [v for v in range(1,10) if v not in {f[0] for f in frames} and v != 5]
    # Determine marker by the color with fewest occurrences (typically one/two isolated markers).
    counts = {v:sum(x==v for row in grid for x in row) for v in marker_colors}
    fill = min(marker_colors, key=lambda v:(counts[v],v)) if marker_colors else 1
    for fc,r0,r1,c0,c1 in frames:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                if r in (r0,r1) or c in (c0,c1): out[r][c]=fc
                elif (r-r0+c-c0)%2 == 1: out[r][c]=fill
    return out

